# Merge Triplets to Form Target Triplet
# Idea: We can solve this problem by iterating through the triplets and checking if each triplet can contribute to forming the target triplet. The idea is to keep track of the maximum values encountered for each element in the t…
# Line comments below keep the same logic as the NeetCode 150 repo solution.

class Solution:
    def mergeTriplets(self, triplets: List[List[int]], target: List[int]) -> bool:
        max_values = [0, 0, 0]

        for triplet in triplets:
            if (
                triplet[0] <= target[0]
                and triplet[1] <= target[1]
                and triplet[2] <= target[2]
            ):
                max_values = [max(max_values[i], triplet[i]) for i in range(3)]

        return max_values == target
